/* Rendrakás a Szükség Szobájában — offline cache (generated by build.mjs; do not edit pages/sw.js by hand).
   The cache name carries a hash of every file, so a new upload replaces the old cache on the next visit.
   The page itself is fetched network-first (a reload shows the newest upload), everything else cache-first.
   First visit (PERF-PLAN.md 6.W13): nothing big is precached while the game loads its own files; whatever the page
   fetches is cached as it goes, and the rest of the site is precached only when the page asks for it after the
   first play session (message 'precache'). */
const CACHE = 'szukseg-szobaja-5f5df89992';

/* Google Fonts and the three.js modules live in caches of their own, which a version bump does not wipe: the URLs
   are versioned by their hosts, so a stored copy stays right. */
const FONT_CACHE = 'szukseg-szobaja-fonts-1';
const CDN_CACHE = 'szukseg-szobaja-cdn-three-0.160.0';
/* The player's own music (assets/music/zene-N.mp3 / .ogg / .m4a, uploaded on GitHub without a build): never precached,
   cached at run time when a track is first played (cache-first, so it also plays offline), kept across versions. */
const MUSIC_CACHE = 'szukseg-szobaja-music-1';
const MUSIC_RE = /\/assets\/music\/zene-\d{1,3}\.(mp3|ogg|m4a)$/i;
/* Offline music is capped (DECISIONS.md 15): the most recently played 10 tracks or about 60 MB, whichever is smaller;
   an evicted track simply streams again. */
const MUSIC_MAX_TRACKS = 10;
const MUSIC_MAX_BYTES = 60 * 1024 * 1024;
const FONT_HOSTS = ['fonts.googleapis.com', 'fonts.gstatic.com'];

