const FONT_SHEETS = [
  'https://fonts.googleapis.com/css2?family=Abril+Fatface&family=Titan+One&family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Source+Sans+3:wght@400;600;700&display=swap',
  'https://fonts.googleapis.com/css2?family=Almendra&family=Uncial+Antiqua&display=swap',
];

/* The font stylesheets and the latin / latin-ext font files they name are fetched at install, because the first
   page load runs before this worker controls the page. Files already stored are not fetched again. */
async function precacheFonts() {
  const cache = await caches.open(FONT_CACHE);
  for (const url of FONT_SHEETS) {
    let res = await cache.match(url, { ignoreVary: true });
    if (!res) {
      res = await fetch(url, { mode: 'cors' }).catch(() => null);
      if (!res || !res.ok) continue;
      await cache.put(url, res.clone());
    }
    const parts = (await res.text()).split('@font-face');
    for (let i = 1; i < parts.length; i++) {
      const tag = (parts[i - 1].match(/\/\*\s*([\w-]+)\s*\*\/\s*$/) || [])[1];
      const file = (parts[i].match(/url\((https:\/\/fonts\.gstatic\.com\/[^)]+)\)/) || [])[1];
      if (!file || (tag && tag !== 'latin' && tag !== 'latin-ext')) continue;
      if (await cache.match(file, { ignoreVary: true })) continue;
      const f = await fetch(file, { mode: 'cors' }).catch(() => null);
      if (f && f.ok) await cache.put(file, f);
    }
  }
}

async function precacheCdn() {
  const cache = await caches.open(CDN_CACHE);
  for (const url of CDN) {
    if (await cache.match(url)) continue;
    const res = await fetch(url, { mode: 'cors' }).catch(() => null);
    if (res && res.ok) await cache.put(url, res);
  }
}

/* Only the small app shell at install: the game's own requests fill the cache while it loads (cache as you go). */
const SHELL = ['./', './index.html', './manifest.webmanifest'];

self.addEventListener('install', (e) => {
  e.waitUntil(
    caches.open(CACHE)
      .then((c) => c.addAll(SHELL))
      .then(() => self.skipWaiting())
      .catch(() => self.skipWaiting())
  );
});

/* Everything not cached yet, one file at a time (asked by the page after the first play session, when idle). */
let precaching = null;
async function precacheRest() {
  const cache = await caches.open(CACHE);
  for (const f of FILES) {
    if (await cache.match(f, { ignoreSearch: true })) continue;
    const res = await fetch(f, { cache: 'no-cache' }).catch(() => null);
    if (res && res.ok) await cache.put(f, res);
  }
  await precacheFonts().catch(() => {});
  await precacheCdn().catch(() => {});
}

self.addEventListener('message', (e) => {
  // The page asks whether this worker handles the music probes (an older worker does not answer).
  if (e.data && e.data.type === 'music?' && e.ports && e.ports[0]) e.ports[0].postMessage({ music: 1 });
  if (e.data && e.data.type === 'precache') {
    if (!precaching) precaching = precacheRest().catch(() => {}).finally(() => { precaching = null; });
    if (e.waitUntil) e.waitUntil(precaching);
  }
});
self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      // Every GitHub Pages repo of the user shares one origin and so one Cache Storage: only this game's own old caches
      // (the 'szukseg-szobaja-' prefix) are removed, never another game's.
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('szukseg-szobaja-') && k !== CACHE && k !== FONT_CACHE && k !== CDN_CACHE && k !== MUSIC_CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

function fromCache(cacheName, req) {
  return caches.open(cacheName).then((cache) => cache.match(req, { ignoreVary: true }).then((hit) => hit || fetch(req).then((res) => {
    if (res && (res.ok || res.type === 'opaque')) cache.put(req, res.clone());
    return res;
  }))).catch(() => Response.error());
}

/* A changed upload under the same name replaces the cached copy (compared by ETag, Last-Modified and length). */
function sameFile(a, b) {
  for (const h of ['etag', 'last-modified', 'content-length']) {
    const x = a.headers.get(h);
    const y = b.headers.get(h);
    if (x && y && x !== y) return false;
  }
  return true;
}

/* Music requests. A probe (header x-music-probe: 1) answers 200 = the track exists, 204 = it does not; the network is
   asked with HEAD (one-byte GET if HEAD is refused), so a missing file never reaches the page as a 404 and nothing is
   downloaded. A play request is cache-first; only complete 200 responses are stored, never a 404. */
async function musicFetch(req) {
  const key = new URL(req.url).pathname;
  const cache = await caches.open(MUSIC_CACHE);
  const hit = await cache.match(key);
  if (req.headers.get('x-music-probe') === '1') {
    let head = null;
    try {
      head = await fetch(req.url, { method: 'HEAD', cache: 'no-store' });
      if (head.status === 405 || head.status === 501) head = await fetch(req.url, { headers: { Range: 'bytes=0-0' }, cache: 'no-store' });
    } catch {
      head = null;
    }
    if (!head) return new Response(null, { status: hit ? 200 : 204 });
    if (head.status !== 200 && head.status !== 206) {
      if (hit && (head.status === 404 || head.status === 410)) await cache.delete(key);
      return new Response(null, { status: 204 });
    }
    if (hit && head.status === 200 && !sameFile(hit, head)) await cache.delete(key);
    return new Response(null, { status: 200 });
  }
  if (hit) {
    // Least recently used order: a played track moves to the end of the cache.
    await cache.put(key, hit.clone()).catch(() => {});
    return hit;
  }
  const res = await fetch(req.url, { cache: 'no-store' });
  if (res && res.status === 200) {
    await cache.put(key, res.clone()).catch(() => {});
    await musicTrim(cache).catch(() => {});
  }
  return res;
}

/** Evicts the least recently played tracks beyond 10 files or about 60 MB (the newest one always stays). */
async function musicTrim(cache) {
  const keys = await cache.keys();
  const sizes = [];
  let total = 0;
  for (const k of keys) {
    const r = await cache.match(k);
    let len = r ? +(r.headers.get('content-length') || 0) : 0;
    if (r && !len) len = (await r.clone().blob()).size;
    sizes.push(len);
    total += len;
  }
  for (let i = 0; i < keys.length - 1; i++) {
    if (keys.length - i <= MUSIC_MAX_TRACKS && total <= MUSIC_MAX_BYTES) break;
    await cache.delete(keys[i]);
    total -= sizes[i];
  }
}

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (FONT_HOSTS.includes(url.hostname)) {
    e.respondWith(fromCache(FONT_CACHE, req));
    return;
  }
  if (url.hostname === 'cdn.jsdelivr.net') {
    e.respondWith(fromCache(CDN_CACHE, req));
    return;
  }
  if (url.origin !== self.location.origin) return;
  if (MUSIC_RE.test(url.pathname)) {
    e.respondWith(musicFetch(req).catch(() => new Response(null, { status: 204 })));
    return;
  }
  const isPage = req.mode === 'navigate' || url.pathname.endsWith('/') || url.pathname.endsWith('.html');
  if (isPage) {
    // Network first with a short timeout, so a new upload shows on reload, but the game still opens offline.
    e.respondWith(new Promise((resolve) => {
      let done = false;
      const fallback = () => caches.match('./index.html').then((hit) => hit || caches.match(req)).then((hit) => {
        if (!done) {
          done = true;
          resolve(hit || Response.error());
        }
      });
      const timer = setTimeout(fallback, 4000);
      fetch(req).then((res) => {
        clearTimeout(timer);
        if (res && res.ok) {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put(req, copy));
        }
        if (!done) {
          done = true;
          resolve(res);
        }
      }).catch(() => {
        clearTimeout(timer);
        fallback();
      });
    }));
    return;
  }
  e.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
      if (res && res.status === 200 && res.type === 'basic') {
        const copy = res.clone();
        caches.open(CACHE).then((c) => c.put(req, copy));
      }
      return res;
    }))
  );
});
